import{_ as e,c as o,o as c,a4 as t}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q11：JavaScript 的数据类型有哪些？typeof 和 instanceof 的区别？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q11.md","filePath":"frontend/q11.md","lastUpdated":null}'),d={name:"frontend/q11.md"},n=t('<h1 id="q11-javascript-的数据类型有哪些-typeof-和-instanceof-的区别" tabindex="-1">Q11：JavaScript 的数据类型有哪些？<code>typeof</code> 和 <code>instanceof</code> 的区别？ <a class="header-anchor" href="#q11-javascript-的数据类型有哪些-typeof-和-instanceof-的区别" aria-label="Permalink to &quot;Q11：JavaScript 的数据类型有哪些？`typeof` 和 `instanceof` 的区别？&quot;">​</a></h1><p><strong>数据类型</strong></p><ul><li><strong>基本类型（7种）</strong>：<code>Number</code>, <code>String</code>, <code>Boolean</code>, <code>undefined</code>, <code>null</code>, <code>Symbol</code>, <code>BigInt</code>。数据存储于栈内存，按值访问。</li><li><strong>引用类型</strong>：<code>Object</code>（包含 <code>Array</code>, <code>Function</code>, <code>Date</code>, <code>RegExp</code> 等）。存储于堆内存，变量保存的是指向堆内存的引用地址。</li></ul><p><strong><code>typeof</code> 运算符</strong></p><ul><li>能准确判断基本类型，但有两个著名“陷阱”： <ul><li><code>typeof null === &#39;object&#39;</code> （历史遗留 bug）</li><li><code>typeof function(){} === &#39;function&#39;</code> （在对象里特殊处理）</li></ul></li><li>无法细分 <code>Array</code>、<code>Date</code>、正则等，它们都返回 <code>&#39;object&#39;</code>。</li></ul><p><strong><code>instanceof</code> 运算符</strong></p><ul><li>用于检测构造函数的 <code>prototype</code> 属性是否出现在某个实例对象的原型链上。</li><li><code>[] instanceof Array</code> 为 <code>true</code>，<code>new Date() instanceof Object</code> 也为 <code>true</code>。</li><li>适合判断引用类型的归属，但对基本类型（字面量）不能直接判断，如 <code>&#39;hello&#39; instanceof String</code> 为 <code>false</code>。</li><li>可以通过 <code>Object.prototype.toString.call()</code> 准确获取类型：<code>[object Array]</code>。</li></ul>',7),a=[n];function i(r,l,s,p,f,_){return c(),o("div",null,a)}const y=e(d,[["render",i]]);export{g as __pageData,y as default};
